// Текст напоминания и две кнопки. Никакой модели здесь нет и не нужно:
// сообщение шаблонное, значит стоит ноль токенов.
// Метки ролей больше не читаются из окружения (решение штаба 20.08).
// Напоминание уходит гостю — ему служебная метка не нужна вовсе.
const out = [];
for (const item of $input.all()) {
  const b = item.json;
  const t = String(b.booking_time || '').slice(0, 5);
  const d = new Date(b.booking_date).toLocaleDateString('ru-RU',
            { day: 'numeric', month: 'long' });

  // WhatsApp вне 24-часового окна требует утверждённого шаблона Meta, а он не подан.
  // Поэтому напоминаем в Telegram, а по остальным каналам зовём администратора.
  out.push({ json: { ...b,
    can_message: b.channel === 'telegram',
    reminder_text:
      `Здравствуйте! Напоминаем о вашей брони в ресторане «Базилик».\n\n` +
      `📅 ${d} в ${t}, ${b.party_size} чел.\n` +
      `Номер брони: ${b.booking_ref}\n\n` +
      `Подтвердите, пожалуйста, что придёте — мы держим стол 15 минут от заявленного времени.`,
    cb_confirm: `booking_confirm:${b.booking_ref}`,
    cb_cancel:  `booking_cancel:${b.booking_ref}`,
  }});
}
return out;
